import { useEffect, useState } from 'react';
import { JLPTLevel, VocabWord, WordleWord } from '../types';
import { KanjiWritingItem, KANJI_WRITING_LIST } from './kanjiStrokeData';
import { VOCAB_LIST } from './vocabData';
import { WORDLE_WORDS } from './wordleWords';

/**
 * Bulk content lives in public/data/ rather than the JS bundle: it is tens of
 * thousands of entries generated by scripts/build-content.ts from open
 * datasets, and only the level the learner picked is ever fetched.
 *
 * The hand-written entries in src/data/ stay bundled. They carry the Nepali
 * translations and example sentences, so they load instantly and come first.
 */
export interface ContentPack {
  wordle: WordleWord[];
  vocab: VocabWord[];
  kanji: KanjiWritingItem[];
  /** False until the generated data for this level has arrived. */
  complete: boolean;
}

const curatedFor = (level: JLPTLevel): ContentPack => ({
  wordle: WORDLE_WORDS.filter(w => w.jlpt === level),
  vocab: VOCAB_LIST.filter(v => v.jlpt === level),
  kanji: KANJI_WRITING_LIST.filter(k => k.level === level),
  complete: false
});

const cache = new Map<JLPTLevel, ContentPack>();
const inFlight = new Map<JLPTLevel, Promise<ContentPack>>();

async function fetchJson<T>(url: string): Promise<T[]> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: ${res.status}`);
  const data = await res.json();
  return Array.isArray(data) ? data : [];
}

export async function loadContentPack(level: JLPTLevel): Promise<ContentPack> {
  const cached = cache.get(level);
  if (cached) return cached;

  const existing = inFlight.get(level);
  if (existing) return existing;

  const slug = level.toLowerCase();
  const promise = (async () => {
    const curated = curatedFor(level);
    try {
      const [wordle, vocab, kanji] = await Promise.all([
        fetchJson<WordleWord>(`/data/wordle-${slug}.json`),
        fetchJson<VocabWord>(`/data/vocab-${slug}.json`),
        fetchJson<KanjiWritingItem>(`/data/kanji-${slug}.json`)
      ]);
      const pack: ContentPack = {
        wordle: [...curated.wordle, ...wordle],
        vocab: [...curated.vocab, ...vocab],
        kanji: [...curated.kanji, ...kanji],
        complete: true
      };
      cache.set(level, pack);
      return pack;
    } catch {
      // Offline or data not deployed: the curated set alone keeps the app usable
      return curated;
    } finally {
      inFlight.delete(level);
    }
  })();

  inFlight.set(level, promise);
  return promise;
}

/**
 * Content for one JLPT level. `ready` stays false until the generated data has
 * loaded, so callers that must choose a stable item (the daily Wordle word)
 * can wait instead of picking from the curated subset and then changing it.
 */
export function useContentPack(level: JLPTLevel): { pack: ContentPack; ready: boolean } {
  const [pack, setPack] = useState<ContentPack>(() => cache.get(level) ?? curatedFor(level));
  const [ready, setReady] = useState<boolean>(() => cache.has(level));

  useEffect(() => {
    const cached = cache.get(level);
    if (cached) {
      setPack(cached);
      setReady(true);
      return;
    }

    let active = true;
    setPack(curatedFor(level));
    setReady(false);
    loadContentPack(level).then(loaded => {
      if (!active) return;
      setPack(loaded);
      setReady(true);
    });
    return () => {
      active = false;
    };
  }, [level]);

  return { pack, ready };
}
